import jax
import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Dict, Any, Sequence

def get_sinusoidal_embeddings(n_position, d_hid):
    position = jnp.arange(n_position)[:, jnp.newaxis]
    div_term = jnp.exp(jnp.arange(0, d_hid, 2) * -(jnp.log(10000.0) / d_hid))
    pe = jnp.zeros((n_position, d_hid))
    pe = pe.at[:, 0::2].set(jnp.sin(position * div_term))
    pe = pe.at[:, 1::2].set(jnp.cos(position * div_term))
    return pe

class ResidualDSConvBlock(nn.Module):
    features: int
    kernel_size: int
    dilation: int

    @nn.compact
    def __call__(self, x):
        residual = x

        y = nn.Conv(features=x.shape[-1], kernel_size=(self.kernel_size,), padding='SAME', kernel_dilation=(self.dilation,), feature_group_count=x.shape[-1])(x)
        y = nn.Conv(features=self.features, kernel_size=(1,))(y)
        y = nn.relu(y)

        if residual.shape[-1] != self.features:
            residual = nn.Conv(features=self.features, kernel_size=(1,), name='projection')(residual)

        return nn.relu(residual + y)

class StackedResidualDSConvCNN(nn.Module):
    d_output: int
    task_type: str
    hidden_dim: int = 128
    dropout_rate: float = 0.1 # Changed from 0.2
    pos_encoding_dim: int = 16
    dilation_rates: Sequence[int] = (1, 2, 4)

    @nn.compact
    def __call__(self, x, deterministic=True):
        seq_len = x.shape[1]

        pos_enc = get_sinusoidal_embeddings(seq_len, self.pos_encoding_dim)
        pos_enc_broadcasted = jnp.broadcast_to(pos_enc, (x.shape[0], seq_len, self.pos_encoding_dim))
        y = jnp.concatenate([x, pos_enc_broadcasted], axis=-1)

        y = nn.Conv(features=self.hidden_dim, kernel_size=(5,), padding='SAME')(y)
        y = nn.relu(y)
        y = nn.Dropout(rate=self.dropout_rate)(y, deterministic=deterministic)

        current_features = self.hidden_dim
        for rate in self.dilation_rates:
            current_features *= 2
            y = ResidualDSConvBlock(features=current_features, kernel_size=5, dilation=rate)(y)
            y = nn.Dropout(rate=self.dropout_rate)(y, deterministic=deterministic)

        y = jnp.mean(y, axis=1)
        y = nn.Dense(features=self.d_output)(y)

        if self.task_type == "regression":
            return y.squeeze(-1)
        else:
            return y

class CNNetworkWrapper:
    def __init__(self, **kwargs):
        self.network = StackedResidualDSConvCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        variables = self.network.init(rng_key, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        rngs = {'dropout': rng_key} if not deterministic else None
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs=rngs)

def create_network(hparams: Dict[str, Any]):
    return CNNetworkWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        hidden_dim=hparams.get("hidden_dim"),
        dropout_rate=hparams.get("dropout_rate"),
        pos_encoding_dim=hparams.get("pos_encoding_dim"),
        dilation_rates=hparams.get("dilation_rates")
    )

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 128,
        'dropout_rate': 0.1, # Changed from 0.2
        'pos_encoding_dim': 16,
        'dilation_rates': (1, 2, 4)
    }

def create_optimizer(learning_rate: float = 0.001):
    total_steps = 50000 
    warmup_steps = 500

    schedule = optax.warmup_cosine_decay_schedule(
        init_value=0.0,
        peak_value=learning_rate,
        warmup_steps=warmup_steps,
        decay_steps=total_steps,
        end_value=1e-5
    )

    return optax.adamw(learning_rate=schedule, weight_decay=0.01)
